/// <summary>
/// Updates the inventory table module.
/// </summary>
/// <param name="_updatePriceDate">Flag to indicate if price date should be updated.</param>
/// <param name="_updatePrice">Flag to indicate if price should be updated.</param>
public void update(boolean _updatePriceDate, boolean _updatePrice)
{
    // Skip business events processing for this update operation
    METCheckSkipBusinessEventsHelper::shouldSkipBusinessEvents(this);

    next update(_updatePriceDate, _updatePrice);
}
